page.css:
/* calm, soft depth */
.feedback-page .criterion { box-shadow: 0 1px 2px rgb(0 0 0 / .04), 0 10px 28px -18px rgb(0 0 0 / .16); transition: none; border-radius: 16px; padding: 18px 20px 18px 24px; }
.feedback-page .criterion:hover { transform: none; }
.feedback-page .criterion::before { width: 4px; opacity: .55; }
.feedback-page .overall { border-radius: 16px; padding: 18px 20px; background: linear-gradient(135deg, var(--a), color-mix(in srgb, var(--a) 70%, #1d3b33)); box-shadow: 0 14px 30px -18px color-mix(in srgb, var(--a) 80%, transparent); }
.feedback-page .overall > span { font-size: 15px; font-weight: 600; }
.feedback-page .chart { padding-top: 16px; }
.feedback-page .field-label { color: var(--a); }
.feedback-page .field-suggestions { padding: 12px 14px; border-radius: 10px; background: color-mix(in srgb, var(--a) 6%, var(--c)); }
.feedback-page .field-suggestions li::before { content: '→'; left: 2px; }
.feedback-page h1 { font-size: 28px; letter-spacing: -.02em; }
